package vn.eduassistant.backend.web;

import com.google.zxing.BarcodeFormat;
import com.google.zxing.client.j2se.MatrixToImageWriter;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.qrcode.QRCodeWriter;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import vn.eduassistant.backend.core.ApiResponse;
import vn.eduassistant.backend.core.ApiException;
import vn.eduassistant.backend.core.Json;
import vn.eduassistant.backend.db.JdbcSupport;
import vn.eduassistant.backend.service.*;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.ByteArrayOutputStream;
import java.util.*;

@RestController
public class AuthController {
    private final AuthService auth;private final UserService users;private final AuditService audits;private final JdbcSupport db;
    public AuthController(AuthService auth,UserService users,AuditService audits,JdbcSupport db){this.auth=auth;this.users=users;this.audits=audits;this.db=db;}
    @PostMapping("/api/login") public ResponseEntity<?> login(@RequestBody Map<String,Object> req,HttpServletResponse response){String username=Json.str(req.get("username")).trim(),password=Json.str(req.get("password")),otp=first(Json.str(req.get("twoFactorCode")),Json.str(req.get("otpCode")));Map<String,Object> result=auth.login(username,password,otp,response);if(result.containsKey("success"))return ResponseEntity.ok(result);return ApiResponse.success(200,"Tài khoản yêu cầu mã xác thực 2 bước (2FA).",result);}
    @PostMapping("/api/auth/2fa/login") public ResponseEntity<?> login2fa(@RequestBody Map<String,Object> req,HttpServletResponse response){String otp=Json.str(req.get("otpCode"));try{return ResponseEntity.ok(auth.login2fa(Json.str(req.get("userId")),Json.str(req.get("tempToken")),otp,response));}catch(ApiException e){throw e;}}
    @PostMapping("/api/register") public ResponseEntity<?> register(){return ApiResponse.failure(403,false,"Public registration is disabled. Student accounts are created by an administrator.",null,"PUBLIC_REGISTRATION_DISABLED");}
    @PostMapping("/api/auth/refresh") public ResponseEntity<?> refresh(HttpServletRequest req,HttpServletResponse res){String csrf=auth.refresh(req,res);return ApiResponse.success(200,"Làm mới phiên đăng nhập thành công.",UserService.map("csrfToken",csrf));}
    @PostMapping("/api/auth/logout") public ResponseEntity<?> logout(HttpServletRequest req,HttpServletResponse res){auth.logout(req,res);return ApiResponse.success(200,"Đăng xuất thành công.");}
    @GetMapping("/api/auth/csrf") public ResponseEntity<?> csrf(HttpServletRequest req,HttpServletResponse res){boolean session=auth.cookie(req,"edu_access")!=null||auth.cookie(req,"edu_refresh")!=null;String token=auth.csrf(req,res);return ApiResponse.success(200,session?"CSRF token đã sẵn sàng.":"Không có phiên đăng nhập.",UserService.map("csrfToken",token,"hasSession",session));}
    @GetMapping("/api/auth/me") public ResponseEntity<?> me(HttpServletRequest req,HttpServletResponse res){Map<String,Object> user=auth.currentUser(req),full=users.userById(Json.str(user.get("id")));if(full==null)return ApiResponse.failure(404,false,"Không tìm thấy người dùng.",null,"NOT_FOUND");Map<String,Object> clean=JdbcSupport.copyWithout(full,"password","twoFactorSecret");String csrf=auth.csrf(req,res);Map<String,Object>data=new LinkedHashMap<String,Object>();data.put("csrfToken",csrf);data.put("user",clean);data.putAll(clean);return ApiResponse.success(200,"Lấy thông tin tài khoản thành công.",data);}
    @PutMapping("/api/auth/profile") public ResponseEntity<?> profile(@RequestBody Map<String,Object> body,HttpServletRequest req){Map<String,Object> user=auth.currentUser(req);Map<String,Object> updates=new LinkedHashMap<String,Object>();for(String k:Arrays.asList("fullName","bio","avatar","department","email","studentCode"))if(body.containsKey(k)&&body.get(k)!=null)updates.put(k,body.get(k));if(updates.isEmpty())return ApiResponse.failure(400,false,"Không có thông tin cần cập nhật.",null,"NO_DATA");Map<String,Object> updated=JdbcSupport.copyWithout(users.updateProfile(Json.str(user.get("id")),updates,user),"password","twoFactorSecret");Map<String,Object>d=new LinkedHashMap<String,Object>();d.put("user",updated);d.putAll(updated);return ApiResponse.success(200,"Cập nhật thông tin thành công!",d);}
    @RequestMapping(value="/api/auth/change-password",method={RequestMethod.PUT,RequestMethod.POST}) public ResponseEntity<?> changePassword(@RequestBody Map<String,Object> body,HttpServletRequest req){Map<String,Object> user=auth.currentUser(req);try{users.changePassword(Json.str(user.get("id")),Json.str(body.get("oldPassword")),Json.str(body.get("newPassword")),user);return ApiResponse.success(200,"Đổi mật khẩu thành công. Các phiên đăng nhập khác đã được thu hồi an toàn.");}catch(IllegalArgumentException e){return ApiResponse.failure(400,false,e.getMessage(),null,"PASSWORD_CHANGE_FAILED");}}
    @DeleteMapping("/api/auth/account") public ResponseEntity<?> deleteAccount(@RequestBody(required=false) Map<String,Object> body,HttpServletRequest req){Map<String,Object> user=auth.currentUser(req),stored=users.userById(Json.str(user.get("id")));if(stored==null)return ApiResponse.failure(404,false,"Tài khoản không tồn tại.",null,"NOT_FOUND");String password=body==null?"":Json.str(body.get("password"));if(!password.isEmpty()&&!users.passwordMatches(password,Json.str(stored.get("password"))))return ApiResponse.failure(400,false,"Mật khẩu xác nhận không chính xác.",null,"INVALID_PASSWORD");try{db.update("DELETE FROM users WHERE id=?",user.get("id"));return ApiResponse.success(200,"Xóa tài khoản thành công.");}catch(Exception e){return ApiResponse.failure(409,false,"Không thể xóa tài khoản đang được tham chiếu bởi hồ sơ.",null,"ACCOUNT_IN_USE");}}
    @PostMapping("/api/auth/2fa/generate") public ResponseEntity<?> generate2fa(HttpServletRequest req){Map<String,Object> user=auth.currentUser(req),stored=users.userById(Json.str(user.get("id")));String secret=auth.newTotpSecret(),uri="otpauth://totp/EDUASSISTANT%20(University%20Portal):"+url(Json.str(stored.get("username")))+"?secret="+secret+"&issuer=EDUASSISTANT%20(University%20Portal)";try{BitMatrix matrix=new QRCodeWriter().encode(uri,BarcodeFormat.QR_CODE,256,256);ByteArrayOutputStream out=new ByteArrayOutputStream();MatrixToImageWriter.writeToStream(matrix,"PNG",out);String dataUrl="data:image/png;base64,"+Base64.getEncoder().encodeToString(out.toByteArray());auth.setTotpSecret(Json.str(user.get("id")),secret);return ApiResponse.success(200,"Tạo mã bí mật 2FA thành công.",UserService.map("secret",secret,"qrCodeUrl",dataUrl,"otpauthUrl",uri));}catch(Exception e){return ApiResponse.failure(500,false,"Không thể tạo mã QR 2FA.",null,"QR_GENERATION_FAILED");}}
    @PostMapping("/api/auth/2fa/enable") public ResponseEntity<?> enable2fa(@RequestBody Map<String,Object> body,HttpServletRequest req){Map<String,Object> user=auth.currentUser(req),stored=users.userById(Json.str(user.get("id")));String secret=first(Json.str(stored.get("twoFactorSecret")),Json.str(body.get("secret"))),token=first(Json.str(body.get("token")),Json.str(body.get("otpCode")));if(secret.isEmpty())return ApiResponse.failure(400,false,"Chưa tạo mã bí mật 2FA. Vui lòng gọi /api/auth/2fa/generate trước.",null,"NO_SECRET");if(!auth.verifyTotp(secret,token))return ApiResponse.failure(400,false,"Mã TOTP 6 số không hợp lệ hoặc đã hết hạn.",null,"INVALID_TOKEN");if(stored.get("twoFactorSecret")==null&&!Json.str(body.get("secret")).isEmpty())auth.setTotpSecret(Json.str(user.get("id")),secret);auth.setTotpEnabled(Json.str(user.get("id")),true);audits.log("2FA_ENABLED",user,UserService.map("twoFactorEnabled",true),"SUCCESS","Bật bảo mật xác thực 2 bước (2FA Google Authenticator) thành công");return ApiResponse.success(200,"Kích hoạt xác thực 2 bước (2FA) thành công.");}
    @PostMapping("/api/auth/2fa/disable") public ResponseEntity<?> disable2fa(@RequestBody(required=false) Map<String,Object> body,HttpServletRequest req){Map<String,Object> user=auth.currentUser(req),stored=users.userById(Json.str(user.get("id")));if(!Json.bool(stored.get("twoFactorEnabled")))return ApiResponse.success(200,"Xác thực 2 bước hiện chưa được bật.");String otp=body==null?"":first(Json.str(body.get("token")),Json.str(body.get("otpCode"))),password=body==null?"":Json.str(body.get("password"));boolean valid=!otp.isEmpty()&&auth.verifyTotp(Json.str(stored.get("twoFactorSecret")),otp)||!password.isEmpty()&&users.passwordMatches(password,Json.str(stored.get("password")));if(!valid)return ApiResponse.failure(400,false,"Vui lòng cung cấp mã OTP 2FA hoặc mật khẩu tài khoản để xác nhận tắt 2FA.",null,"AUTHENTICATION_REQUIRED");auth.setTotpEnabled(Json.str(user.get("id")),false);audits.log("AUTH_2FA_DISABLED",user,UserService.map("userId",user.get("id")),"SUCCESS","Người dùng đã xác thực và tắt 2FA an toàn");return ApiResponse.success(200,"Đã tắt xác thực 2 bước an toàn.");}
    private static String first(String...values){for(String v:values)if(v!=null&&!v.trim().isEmpty())return v;return "";}
    private static String url(String value){try{return java.net.URLEncoder.encode(value,"UTF-8");}catch(Exception e){return value;}}
}
